files.hooks/sizes.ts:
// Size column of the Files tab. The folder calculation with `du -sk` comes from filetree
// (MIT, Kurt Buhler; see LICENSE-filetree); here only the pure parts: parsing, format and the cache for the session.
import { ancestors } from './tree'

// Bytes in short form, base 1000 like the Finder: "999 B", "14 kB", "6,1 MB", "48 MB". `mark`: the decimal mark
// of the language (the catalog's files.decimalMark).
export function formatSize(bytes: number, mark: string): string {
  if (bytes < 1000) return `${bytes} B`
  const kb = Math.round(bytes / 1000)
  if (kb < 1000) return `${kb} kB`
  const units: [string, number][] = [['MB', 1e6], ['GB', 1e9], ['TB', 1e12]]
  for (const [unit, div] of units) {
    const v = bytes / div
    if (v < 999.5 || unit === 'TB') return v < 9.95 ? `${v.toFixed(1).replace('.', mark)} ${unit}` : `${Math.round(v)} ${unit}`
  }
  return `${bytes} B`
}

// `du -sk <folder>`: the first column in kilobytes (1024 bytes); null if the output does not have it.
export function parseDu(stdout: string): number | null {
  const m = stdout.match(/^(\d+)\s/)
  return m ? Number(m[1]) * 1024 : null
}

// The visible folders to measure: with no cached value (null means "failed", not repeated) or marked to be
// measured again, and with no `du` already running.
export function duTargets(dirs: readonly string[], sizes: Readonly<Record<string, number | null>>, running: ReadonlySet<string>, stale: ReadonlySet<string>): string[] {
  return dirs.filter(d => (!(d in sizes) || stale.has(d)) && !running.has(d))
}

// After a write the path itself (if it is a moved folder) and the folders that contain it are measured again.
export function staleDirs(paths: readonly string[]): string[] {
  return [...new Set(paths.flatMap(p => [p, ...ancestors(p)]))]
}

files.hooks/edit.ts:
// Raw Markdown editor: pure operations on lines and cursor, a fixed window, undo and redo.
// Used by editor.tsx (the Client). No `$` and no measurement of the surface, except pointAt, which is only
// called from the click handler (never from the drawing).

export type KeyEv = { key: string; ctrl?: true; shift?: true; meta?: true }
export type Doc = { lines: string[]; row: number; col: number }
export type Ed = Doc & {
  // First logical line drawn.
  top: number
  undo: Doc[]
  redo: Doc[]
  // The last action was a typed character: the next one goes into the same step.
  typing: boolean
}
export type Act = 'none' | 'move' | 'edit' | 'save' | 'paste'
export type Out = { ed: Ed; act: Act }

// Logical lines drawn: always this many, whatever the size of the pane.
export const VIEW = 28
// Rows of margin between the cursor and the edge of the window.
export const SCROLLOFF = 3
export const MAX_UNDO = 200
// Columns of the numbering: four digits and a space.
export const GUTTER = 5
// Beyond this many characters a line is cut in the drawing; the cursor's line keeps more.
export const LINE_CLIP = 400
export const CURSOR_CLIP = 4000

const SPECIAL: ReadonlySet<string> = new Set([
  'up', 'down', 'left', 'right', 'return', 'enter', 'tab', 'backspace', 'delete', 'pageup', 'pagedown', 'home', 'end', 'escape',
])

const clamp = (n: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, n))
const snap = (ed: Doc): Doc => ({ lines: ed.lines, row: ed.row, col: ed.col })

// A character outside the BMP (e.g. an emoji) is a surrogate pair: two code units.
const isHigh = (c: number): boolean => c >= 0xd800 && c <= 0xdbff
const isLow = (c: number): boolean => c >= 0xdc00 && c <= 0xdfff
// Code units taken by the character before `col`.
const widthBefore = (s: string, col: number): number =>
  col >= 2 && isLow(s.charCodeAt(col - 1)) && isHigh(s.charCodeAt(col - 2)) ? 2 : 1
// Code units taken by the character that starts at `col`.
const widthAt = (s: string, col: number): number =>
  col + 1 < s.length && isHigh(s.charCodeAt(col)) && isLow(s.charCodeAt(col + 1)) ? 2 : 1
// A column between the two halves of a surrogate pair: moves it to the start of the pair.
const snapCol = (s: string, col: number): number =>
  col > 0 && col < s.length && isHigh(s.charCodeAt(col - 1)) && isLow(s.charCodeAt(col)) ? col - 1 : col

export function fromText(text: string, row = 0, col = 0): Ed {
  const lines = text.split('\n')
  const r = clamp(row, 0, lines.length - 1)
  const c = clamp(col, 0, (lines[r] ?? '').length)
  return { lines, row: r, col: c, top: follow(0, r, lines.length), undo: [], redo: [], typing: false }
}

export const toText = (ed: Doc): string => ed.lines.join('\n')

// First line of the window so that the cursor stays SCROLLOFF lines from the edges.
export function follow(top: number, row: number, total: number): number {
  const maxTop = Math.max(0, total - VIEW)
  let t = top
  if (row < t + SCROLLOFF) t = row - SCROLLOFF
  if (row > t + VIEW - 1 - SCROLLOFF) t = row - (VIEW - 1 - SCROLLOFF)
  return clamp(t, 0, maxTop)
}

function moveTo(ed: Ed, row: number, col: number): Out {
  const r = clamp(row, 0, ed.lines.length - 1)
  const text = ed.lines[r] ?? ''
  const c = snapCol(text, clamp(col, 0, text.length))
  if (r === ed.row && c === ed.col) return { ed: { ...ed, typing: false }, act: 'none' }
  return { ed: { ...ed, row: r, col: c, top: follow(ed.top, r, ed.lines.length), typing: false }, act: 'move' }
}

// A change: it goes into the history, except characters typed in a row, which stay a single step.
function change(ed: Ed, next: Doc, typing: boolean): Out {
  const undo = typing && ed.typing ? ed.undo : [...ed.undo, snap(ed)].slice(-MAX_UNDO)
  return { ed: { ...ed, ...next, top: follow(ed.top, next.row, next.lines.length), undo, redo: [], typing }, act: 'edit' }
}

function history(ed: Ed, isRedo: boolean): Out {
  const from = isRedo ? ed.redo : ed.undo
  const prev = from[from.length - 1]
  if (prev === undefined) return { ed, act: 'none' }
  const rest = from.slice(0, -1)
  const other = [...(isRedo ? ed.undo : ed.redo), snap(ed)]
  const top = follow(ed.top, prev.row, prev.lines.length)
  return { ed: { ...ed, ...prev, top, typing: false, undo: isRedo ? other : rest, redo: isRedo ? rest : other }, act: 'edit' }
}

export function reduce(ed: Ed, ev: KeyEv): Out {
  const k = ev.key
  const line = ed.lines[ed.row] ?? ''
  const { row, col } = ed
  if (ev.meta || ev.ctrl) {
    const lower = k.toLowerCase()
    if (lower === 's') return { ed, act: 'save' }
    if (lower === 'v') return { ed, act: 'paste' }
    if (lower === 'z') return history(ed, ev.shift === true)
    return { ed, act: 'none' }
  }
  switch (k) {
    case 'left': return col > 0 ? moveTo(ed, row, col - widthBefore(line, col)) : row > 0 ? moveTo(ed, row - 1, (ed.lines[row - 1] ?? '').length) : moveTo(ed, row, col)
    case 'right': return col < line.length ? moveTo(ed, row, col + widthAt(line, col)) : row < ed.lines.length - 1 ? moveTo(ed, row + 1, 0) : moveTo(ed, row, col)
    case 'up': return moveTo(ed, row - 1, col)
    case 'down': return moveTo(ed, row + 1, col)
    case 'pageup': return moveTo(ed, row - VIEW, col)
    case 'pagedown': return moveTo(ed, row + VIEW, col)
    case 'home': return moveTo(ed, row, 0)
    case 'end': return moveTo(ed, row, line.length)
    case 'return':
    case 'enter': {
      const lines = [...ed.lines]
      lines.splice(row, 1, line.slice(0, col), line.slice(col))
      return change(ed, { lines, row: row + 1, col: 0 }, false)
    }
    case 'tab': {
      const lines = [...ed.lines]
      lines[row] = `${line.slice(0, col)}  ${line.slice(col)}`
      return change(ed, { lines, row, col: col + 2 }, false)
    }
    case 'backspace': {
      if (col > 0) {
        const w = widthBefore(line, col)
        const lines = [...ed.lines]
        lines[row] = line.slice(0, col - w) + line.slice(col)
        return change(ed, { lines, row, col: col - w }, false)
      }
      if (row === 0) return { ed, act: 'none' }
      const prev = ed.lines[row - 1] ?? ''
      const lines = [...ed.lines]
      lines.splice(row - 1, 2, prev + line)
      return change(ed, { lines, row: row - 1, col: prev.length }, false)
    }
    case 'delete': {
      if (col < line.length) {
        const w = widthAt(line, col)
        const lines = [...ed.lines]
        lines[row] = line.slice(0, col) + line.slice(col + w)
        return change(ed, { lines, row, col }, false)
      }
      if (row >= ed.lines.length - 1) return { ed, act: 'none' }
      const lines = [...ed.lines]
      lines.splice(row, 2, line + (ed.lines[row + 1] ?? ''))
      return change(ed, { lines, row, col }, false)
    }
  }
  const ch = k === 'space' ? ' ' : k
  if (SPECIAL.has(k) || [...ch].length !== 1 || /[\u0000-\u001f\u007f]/.test(ch)) return { ed, act: 'none' }
  const lines = [...ed.lines]
  lines[row] = line.slice(0, col) + ch + line.slice(col)
  return change(ed, { lines, row, col: col + ch.length }, true)
}

// Screen rows of the cursor's line, which wraps in full; the others take one.
const screenRows = (len: number, columns: number): number =>
  Math.max(1, Math.ceil(Math.min(len, CURSOR_CLIP) / Math.max(1, columns - GUTTER)))

// From the click (cells of the region) to the row and column of the text. The column is approximate:
// the desktop draws proportional text; the arrow keys give the precision.
export function pointAt(ed: Ed, x: number, y: number, columns: number): Ed {
  const last = Math.min(ed.lines.length, ed.top + VIEW) - 1
  let at = 0
  let row = ed.top
  let offset = 0
  for (let i = ed.top; i <= last; i++) {
    const rows = i === ed.row ? screenRows((ed.lines[i] ?? '').length, columns) : 1
    row = i
    offset = clamp(y - at, 0, rows - 1)
    if (y < at + rows) break
    at += rows
  }
  const width = Math.max(1, columns - GUTTER)
  const col = (row === ed.row ? offset * width : 0) + x - GUTTER
  return moveTo(ed, Math.max(ed.top, row), col).ed
}

files.hooks/shell.ts:
import type { Verb } from '../types'
import { resolve } from './classify'
import { WRITES } from './theme'

export type ShellTouch = { verb: Verb; path: string; detail?: string }
export type ShellResult = { touches: ShellTouch[]; isUnparsed: boolean }

const READERS = new Set(['cat', 'head', 'tail', 'less', 'more', 'wc', 'bat', 'stat', 'file', 'diff', 'shasum', 'md5'])
const LISTERS = new Set(['ls', 'tree', 'du'])
const SEARCHERS = new Set(['grep', 'egrep', 'fgrep', 'rg', 'ugrep'])
const QUIET = new Set(['echo', 'printf', 'true', 'false', 'sleep', 'date', 'which', 'pwd', 'sort', 'uniq', 'tr', 'cut', 'fold', 'jq', 'xargs', 'export', 'test', '['])
const REDIRECT = /^(\d?>>?|&>)$/
const GREP_VALUE_FLAGS = ['-A', '-B', '-C', '-m', '-e', '-f']
const VALUE_FLAGS: Record<string, Set<string>> = {
  head: new Set(['-n', '-c']),
  tail: new Set(['-n', '-c']),
  tree: new Set(['-L', '-I']),
  sed: new Set(['-e', '-f']),
  grep: new Set(GREP_VALUE_FLAGS),
  egrep: new Set(GREP_VALUE_FLAGS),
  fgrep: new Set(GREP_VALUE_FLAGS),
  ugrep: new Set(GREP_VALUE_FLAGS),
  rg: new Set([...GREP_VALUE_FLAGS, '-g', '-t']),
}

export function splitSegments(command: string): string[] {
  const segments: string[] = []
  let current = ''
  let quote: string | null = null
  let heredoc: string | null = null
  const lines = command.split('\n')
  for (let li = 0; li < lines.length; li++) {
    const line = lines[li] ?? ''
    if (heredoc !== null) {
      if (line.trim() === heredoc) heredoc = null
      continue
    }
    const hd = line.match(/<<-?\s*['"]?(\w+)['"]?/)
    for (let i = 0; i < line.length; i++) {
      const c = line.charAt(i)
      if (quote) {
        current += c
        if (c === quote) quote = null
        continue
      }
      if (c === '"' || c === "'") { quote = c; current += c; continue }
      if (c === '\\' && i + 1 < line.length) { current += c + line.charAt(i + 1); i++; continue }
      const two = line.slice(i, i + 2)
      if (two === '&&' || two === '||') { segments.push(current); current = ''; i++; continue }
      if (c === ';' || (c === '|' && line[i + 1] !== '|')) { segments.push(current); current = ''; continue }
      current += c
    }
    if (!quote) { segments.push(current); current = '' }
    else current += '\n'
    if (hd) heredoc = hd[1] ?? null
  }
  if (current) segments.push(current)
  return segments.map(s => s.trim()).filter(Boolean)
}

type Lexeme = { text: string; isOp: boolean }

// Like tokenize, but marks as operators (isOp) only the redirects/heredocs/inputs that appear unquoted.
function lex(segment: string): Lexeme[] {
  const tokens: Lexeme[] = []
  let current = ''
  let hasToken = false
  let quote: string | null = null
  for (let i = 0; i < segment.length; i++) {
    const c = segment.charAt(i)
    if (quote) {
      if (c === quote) quote = null
      else current += c
      continue
    }
    if (c === '"' || c === "'") { quote = c; hasToken = true; continue }
    if (c === '\\' && i + 1 < segment.length) { current += segment.charAt(i + 1); hasToken = true; i++; continue }
    if (c === ' ' || c === '\t') {
      if (hasToken) tokens.push({ text: current, isOp: false })
      current = ''
      hasToken = false
      continue
    }
    const redirect = segment.slice(i).match(/^(\d?>>?|&>)/)?.[1]
    if (redirect !== undefined && !hasToken) {
      tokens.push({ text: redirect, isOp: true })
      i += redirect.length - 1
      continue
    }
    if (redirect !== undefined && /^\d$/.test(current) && hasToken) {
      tokens.push({ text: current + redirect, isOp: true })
      current = ''
      hasToken = false
      i += redirect.length - 1
      continue
    }
    if (c === '<' && !hasToken) {
      const input = segment.slice(i).match(/^(<<<|<<-|<<|<)/)?.[1] ?? '<'
      tokens.push({ text: input, isOp: true })
      i += input.length - 1
      continue
    }
    current += c
    hasToken = true
  }
  if (hasToken) tokens.push({ text: current, isOp: false })
  return tokens
}

export function tokenize(segment: string): string[] {
  return lex(segment).map(t => t.text)
}

const dirOf = (p: string): string => (p.includes('/') ? p.slice(0, p.lastIndexOf('/')) || '/' : '.')
const isGlob = (p: string): boolean => /[*?]/.test(p)

// The variables assigned in the command itself (`NEW=/tmp/x; mkdir $NEW/a`) are substituted. A variable
// the command does not assign, or a `$(…)` substitution, leaves the path unknown: null.
function expand(p: string, vars: ReadonlyMap<string, string>): string | null {
  if (/`|\$\(/.test(p)) return null
  let isKnown = true
  const out = p.replace(/\$\{(\w+)\}|\$(\w+)/g, (_, a: string | undefined, b: string | undefined) => {
    const v = vars.get(a ?? b ?? '')
    if (v === undefined) isKnown = false
    return v ?? ''
  })
  return isKnown ? out : null
}

export function parseShell(command: string, cwd: string): ShellResult {
  const touches: ShellTouch[] = []
  let isUnparsed = false
  // An unknown path (unknown variable, or relative after a `cd` we cannot resolve) does not become a
  // vault file: the command stays a plain shell run.
  let isUnknown = false
  const vars = new Map<string, string>()
  let dir: string | null = cwd
  // A path with the variables already substituted, from the current folder; null if it is relative and the folder is unknown.
  const from = (p: string): string | null => (dir === null && !p.startsWith('/') ? null : resolve(dir ?? '/', p))
  const at = (raw: string): string | null => { const p = expand(raw, vars); return p === null ? null : from(p) }
  const add = (verb: Verb, raw: string, detail?: string): void => {
    if (raw === '' || raw.startsWith('~') || raw === '/dev/null' || raw.startsWith('&')) return
    const p = expand(raw, vars)
    const path = p === null ? null : from(isGlob(p) ? dirOf(p) : p)
    if (p === null || path === null) { isUnknown = true; return }
    if (isGlob(p)) {
      if (WRITES.has(verb)) touches.push({ verb, path, detail: p.slice(p.lastIndexOf('/') + 1) })
      else touches.push(detail === undefined ? { verb: 'search', path } : { verb: 'search', path, detail })
    } else touches.push(detail === undefined ? { verb, path } : { verb, path, detail })
  }

  // The move: the source too (in detail, as written) with the variables substituted.
  const move = (to: string, source: string): void => {
    const src = expand(source, vars)
    if (src === null) { isUnknown = true; return }
    add('move', to, src)
  }

  for (const segment of splitSegments(command)) {
    let tokens = lex(segment)
    const assigned: [string, string][] = []
    while (tokens.length && !tokens[0]?.isOp && /^\w+=/.test(tokens[0]?.text ?? '')) {
      const t = tokens[0]?.text ?? ''
      assigned.push([t.slice(0, t.indexOf('=')), t.slice(t.indexOf('=') + 1)])
      tokens = tokens.slice(1)
    }
    // Assignments only: they hold for the rest of the command. In front of a command they hold only for that one.
    if (!tokens.length) {
      for (const [name, value] of assigned) {
        const v = expand(value, vars)
        if (v === null) vars.delete(name)
        else vars.set(name, v)
      }
      continue
    }

    const rest: string[] = []
    for (let i = 0; i < tokens.length; i++) {
      const { text: tok, isOp } = tokens[i] ?? { text: '', isOp: false }
      if (isOp && REDIRECT.test(tok)) {
        const target = tokens[i + 1]?.text
        if (target !== undefined && !tok.startsWith('2')) add('edit', target)
        i++
        continue
      }
      if (isOp && tok.startsWith('<<')) { i++; continue }
      if (isOp && tok === '<') {
        const source = tokens[i + 1]?.text
        if (source !== undefined) add('read', source)
        i++
        continue
      }
      rest.push(tok)
    }
    const [cmd, ...args] = rest
    if (cmd === undefined) continue
    const valueFlags = VALUE_FLAGS[cmd]
    const operands: string[] = []
    for (let i = 0; i < args.length; i++) {
      const a = args[i] ?? ''
      if (valueFlags?.has(a)) { i++; continue }
      if (!a.startsWith('-') || a === '-') operands.push(a)
    }
    const last = operands[operands.length - 1] ?? ''

    if (cmd === 'cd') { dir = at(operands[0] ?? cwd); continue }
    if (QUIET.has(cmd)) continue
    if (READERS.has(cmd)) { operands.filter(o => o !== '-').forEach(o => add('read', o)); continue }
    if (LISTERS.has(cmd)) { (operands.length ? operands : ['.']).forEach(o => add('search', o)); continue }
    if (cmd === 'find') {
      const firstFlag = args.findIndex(a => a.startsWith('-'))
      const paths = firstFlag === -1 ? args : args.slice(0, firstFlag)
      ;(paths.length ? paths : ['.']).forEach(o => add('search', o))
      continue
    }
    if (SEARCHERS.has(cmd)) {
      const eIndex = args.findIndex(a => a === '-e')
      const hasPatternFlag = eIndex >= 0 || args.includes('-f')
      const pattern = eIndex >= 0 ? args[eIndex + 1] : hasPatternFlag ? undefined : operands[0]
      const files = hasPatternFlag ? operands : operands.slice(1)
      if (!files.length) {
        const isRecursive = args.some(a => a === '--recursive' || /^-[A-Za-z]*[rR][A-Za-z]*$/.test(a))
        if (cmd !== 'rg' && !isRecursive) continue
      }
      ;(files.length ? files : ['.']).forEach(o => add('search', o, pattern))
      continue
    }
    if (cmd === 'sed') {
      const isInPlace = args.some(a => a.startsWith('-i'))
      const hasScriptFlag = args.includes('-e') || args.includes('-f')
      const ops = operands.filter(o => o !== '')
      const files = hasScriptFlag ? ops : ops.slice(1)
      files.forEach(o => add(isInPlace ? 'edit' : 'read', o))
      continue
    }
    if (cmd === 'awk') { operands.slice(1).forEach(o => add('read', o)); continue }
    if (cmd === 'touch' || cmd === 'mkdir') { operands.forEach(o => add('create', o)); continue }
    if (cmd === 'rm' || cmd === 'rmdir') { operands.forEach(o => add('delete', o.replace(/\/+$/, ''))); continue }
    if (cmd === 'tee') { operands.forEach(o => add('edit', o)); continue }
    if (cmd === 'mv' && operands.length >= 2) { move(last, operands[0] ?? ''); continue }
    if (cmd === 'cp' && operands.length >= 2) {
      operands.slice(0, -1).forEach(o => add('read', o))
      add('create', last)
      continue
    }
    if (cmd === 'git' && (operands[0] === 'mv' || operands[0] === 'rm')) {
      if (operands[0] === 'rm') operands.slice(1).forEach(o => add('delete', o))
      else if (operands.length >= 3) move(last, operands[1] ?? '')
      continue
    }
    isUnparsed = true
  }
  return { touches, isUnparsed: isUnparsed || isUnknown }
}

// For the Activity log: which programs a command runs, not the whole text (to a reader a truncated
// `python3 /private/tmp/…` says nothing). One program for each segment, with the name without the path; for
// tools with subcommands the subcommand too (`git commit`, `kubectl get`). Without cd, assignments,
// shell words and comments; filters (head, wc, grep…) only if nothing else is left. '' if there is no name.
const WRAPPERS = new Set(['sudo', 'env', 'time', 'nohup', 'command', 'exec', 'builtin', '!', 'if', 'then', 'else', 'elif', 'do', 'while', 'until', '{', '('])
const OPENERS = new Set(['for', 'select', 'case', 'function'])
const SILENT = new Set(['cd', 'pushd', 'popd', 'export', 'source', '.', ':', 'set', 'unset', 'read', 'local', 'declare', 'shift', 'return', 'exit', 'trap', 'wait', 'alias', 'done', 'fi', 'esac', '}', ')'])
const FILTERS = new Set([...QUIET, 'head', 'tail', 'wc', 'grep', 'egrep', 'cat', 'sed', 'awk', 'less', 'more', 'tee'])
const SUB_FLAGS: Record<string, Set<string>> = {
  git: new Set(['-C', '-c']),
  kubectl: new Set(['-n', '--namespace', '--context', '--kubeconfig']),
  helm: new Set(['-n', '--namespace', '--kube-context']),
  docker: new Set(['-H', '--host', '--context']),
  gh: new Set(['-R', '--repo']),
  npm: new Set(['--prefix']),
  pnpm: new Set(['-C', '--dir', '--filter']),
  yarn: new Set(['--cwd']),
  make: new Set(['-C', '-f']),
  go: new Set(['-C']),
}
const SUB = new Set([...Object.keys(SUB_FLAGS), 'bun', 'brew', 'tea', 'claude', 'uv', 'pip', 'pip3', 'cargo', 'poetry', 'conda'])
const depth = (s: string): number => (s.match(/\(/g)?.length ?? 0) - (s.match(/\)/g)?.length ?? 0)

function segmentLabel(segment: string): string {
  const words: string[] = []
  const lexed = lex(segment)
  for (let i = 0; i < lexed.length; i++) {
    const t = lexed[i]
    if (t === undefined) continue
    if (t.isOp) { i++; continue }
    if (t.text.startsWith('#')) break
    words.push(t.text)
  }
  let i = 0
  while (i < words.length) {
    const w = words[i] ?? ''
    if (/^\w+=/.test(w)) {
      // A value with open parentheses (`F=(a b)`, `X=$(git …)`) goes on up to the one that closes them.
      let open = depth(w)
      i++
      while (open > 0 && i < words.length) open += depth(words[i++] ?? '')
      continue
    }
    if (WRAPPERS.has(w)) { i++; continue }
    break
  }
  const prog = words[i] ?? ''
  if (prog === '' || prog.startsWith('$') || OPENERS.has(prog) || SILENT.has(prog)) return ''
  const name = prog.slice(prog.lastIndexOf('/') + 1)
  if (!SUB.has(name)) return name
  const flags = SUB_FLAGS[name]
  for (let j = i + 1; j < words.length; j++) {
    const a = words[j] ?? ''
    if (flags?.has(a)) { j++; continue }
    if (a.startsWith('-')) continue
    return /^[a-z][\w-]*$/i.test(a) ? `${name} ${a}` : name
  }
  return name
}

export function commandLabel(command: string): string {
  const all = [...new Set(splitSegments(command).map(segmentLabel).filter(x => x !== ''))]
  const main = all.filter(x => !FILTERS.has(x.split(' ')[0] ?? ''))
  return (main.length > 0 ? main : all).join(', ')
}

